function threeSumClosest(nums, target) {
    nums.sort((a, b) => a - b);
    let ans = Infinity;
    const n = nums.length;
    for (let i = 0; i < n; ++i) {
        let j = i + 1;
        let k = n - 1;
        while (j < k) {
            const t = nums[i] + nums[j] + nums[k];
            if (t === target) {
                return t;
            }
            if (Math.abs(t - target) < Math.abs(ans - target)) {
                ans = t;
            }
            if (t > target) {
                --k;
            }
            else {
                ++j;
            }
        }
    }
    return ans;
}

